NEW_FILES = {
  "lib/hex-actions.ts": 'import {\n  addLog,\n  content,\n  establishShelter,\n  hexDistance,\n  hexKey,\n  type GameState,\n} from "./game";\nimport { revealSector } from "./sectors";\n\nexport type HexQuickAction =\n  | { type: "observe" }\n  | { type: "travel" }\n  | { type: "establish" }\n  | { type: "infestation"; value: number | null };\n\nexport function hexActionOptions(game: GameState, id: string) {\n  const area = content.hexes.find(hex => hexKey(hex.q, hex.r) === id);\n  const record = game.hexes[id];\n  if (!area || !record) return null;\n\n  const [partyQ, partyR] = (game.partyHex || "0,0").split(",").map(Number);\n  const nearby = hexDistance(area.q - partyQ, area.r - partyR) === 1;\n  const travelMinutes = record.routeHours * 60;\n  const atParty = id === game.partyHex;\n  const canObserve = nearby && record.discovery === "desconhecido";\n  const canTravel = nearby && record.discovery !== "desconhecido" && game.minutes + travelMinutes < 1440;\n  const canEstablish = atParty && record.discovery === "explorado" && !game.shelter.hex;\n  const canRelocate = atParty && record.discovery === "explorado"\n    && Boolean(game.shelter.hex) && game.shelter.hex !== id;\n\n  return {\n    area,\n    record,\n    nearby,\n    travelMinutes,\n    atParty,\n    canObserve,\n    canTravel,\n    canEstablish,\n    canRelocate,\n  };\n}\n\nexport function performHexAction(game: GameState, id: string, action: HexQuickAction) {\n  const options = hexActionOptions(game, id);\n  if (!options) return { ok: false, message: "" };\n  const { area, record } = options;\n\n  if (action.type === "observe") {\n    if (!options.canObserve) return { ok: false, message: "" };\n    const sector = revealSector(game, id);\n    game.hexes[id].discovery = "avistado";\n    const message = `Do limite do hex, o grupo avistou ${sector.name}.`;\n    addLog(game, "avistamento", message);\n    return { ok: true, message };\n  }\n\n  if (action.type === "travel") {\n    if (!options.canTravel) return { ok: false, message: "" };\n    game.minutes += options.travelMinutes;\n    game.partyHex = id;\n    const destination = revealSector(game, id);\n    game.hexes[id].discovery = "explorado";\n    for (const neighbor of content.hexes) {\n      if (hexDistance(neighbor.q - area.q, neighbor.r - area.r) !== 1) continue;\n      const key = hexKey(neighbor.q, neighbor.r);\n      if (game.hexes[key].discovery === "desconhecido") {\n        revealSector(game, key);\n        game.hexes[key].discovery = "avistado";\n      }\n    }\n    const message = `O grupo entrou em ${destination.name} após ${record.routeHours} h de trajeto.`;\n    addLog(game, "travessia", message);\n    return { ok: true, message };\n  }\n\n  if (action.type === "establish") {\n    if (!options.canEstablish || !establishShelter(game, id)) return { ok: false, message: "" };\n    return { ok: true, message: `Abrigo estabelecido em ${game.hexes[id].sector?.name ?? `hex ${id}`}.` };\n  }\n\n  if (action.type === "infestation") {\n    if (action.value !== null && (!Number.isInteger(action.value) || action.value < 0 || action.value > 5))\n      return { ok: false, message: "" };\n    game.hexes[id].infestation = action.value;\n    const message = action.value === null\n      ? `Infestação do hex ${id} voltou a ficar em aberto.`\n      : `Infestação do hex ${id} definida como ${action.value}/5.`;\n    addLog(game, "mapa", message);\n    return { ok: true, message };\n  }\n\n  return { ok: false, message: "" };\n}\n',
  "components/hex-context-menu.tsx": '"use client";\n\nimport type { ReactElement } from "react";\nimport {\n  Bug,\n  Compass,\n  Dice5,\n  Eye,\n  Footprints,\n  House,\n  MapPin,\n  Plus,\n  Route,\n} from "lucide-react";\nimport { toast } from "sonner";\nimport {\n  ContextMenu,\n  ContextMenuContent,\n  ContextMenuItem,\n  ContextMenuLabel,\n  ContextMenuSeparator,\n  ContextMenuSub,\n  ContextMenuSubContent,\n  ContextMenuSubTrigger,\n  ContextMenuTrigger,\n} from "@/components/ui/context-menu";\nimport { hexActionOptions, performHexAction, type HexQuickAction } from "@/lib/hex-actions";\nimport type { GameState } from "@/lib/game";\n\ntype Edit = (fn: (draft: GameState) => void) => void;\ntype Generator = "locais" | "comercios" | "eventos";\n\nexport function HexContextMenu({\n  game,\n  edit,\n  hexId,\n  playerPreview,\n  onOpenDetails,\n  onGenerate,\n  onCreatePoint,\n  onOpenMasterTools,\n  onRelocateShelter,\n  children,\n}: {\n  game: GameState;\n  edit: Edit;\n  hexId: string;\n  playerPreview: boolean;\n  onOpenDetails: () => void;\n  onGenerate: (kind: Generator) => void;\n  onCreatePoint: () => void;\n  onOpenMasterTools: () => void;\n  onRelocateShelter: () => void;\n  children: ReactElement;\n}) {\n  const options = hexActionOptions(game, hexId);\n  if (!options) return children;\n\n  const { record } = options;\n  const title = record.discovery === "desconhecido"\n    ? "Fora do horizonte"\n    : record.sector?.name ?? `Hex ${hexId}`;\n\n  function run(action: HexQuickAction) {\n    let result: ReturnType<typeof performHexAction> | null = null;\n    edit(draft => { result = performHexAction(draft, hexId, action); });\n    if (!result?.ok) {\n      toast.error("A ação não pôde ser concluída.", {\n        description: "Confira a posição do grupo, o horário e o estado do setor.",\n      });\n      return;\n    }\n    toast.success(result.message);\n  }\n\n  return <ContextMenu>\n    <ContextMenuTrigger asChild>{children}</ContextMenuTrigger>\n    <ContextMenuContent className="inventory-context-menu map-context-menu">\n      <ContextMenuLabel className="inventory-context-header">\n        <b>{title}</b>\n        <span>HEX {hexId} · {record.discovery}{record.infestation === null ? " · infestação ?" : ` · infestação ${record.infestation}/5`}</span>\n      </ContextMenuLabel>\n      <ContextMenuSeparator />\n\n      <ContextMenuItem onSelect={onOpenDetails}><MapPin /> Abrir detalhes</ContextMenuItem>\n\n      {!playerPreview && options.canObserve &&\n        <ContextMenuItem onSelect={() => run({ type: "observe" })}><Eye /> Avistar setor</ContextMenuItem>}\n\n      {!playerPreview && options.canTravel &&\n        <ContextMenuItem onSelect={() => run({ type: "travel" })}><Route /> Entrar no hex · {record.routeHours} h</ContextMenuItem>}\n\n      {!playerPreview && options.canEstablish &&\n        <ContextMenuItem onSelect={() => run({ type: "establish" })}><House /> Estabelecer abrigo aqui</ContextMenuItem>}\n\n      {!playerPreview && options.canRelocate &&\n        <ContextMenuItem onSelect={onRelocateShelter}><House /> Mudar abrigo para cá…</ContextMenuItem>}\n\n      {!playerPreview && record.discovery !== "desconhecido" && <>\n        <ContextMenuSeparator />\n        <ContextMenuSub>\n          <ContextMenuSubTrigger><Dice5 /> Gerar conteúdo</ContextMenuSubTrigger>\n          <ContextMenuSubContent className="inventory-context-submenu">\n            <ContextMenuItem onSelect={() => onGenerate("locais")}><Dice5 /> B1 · Local</ContextMenuItem>\n            <ContextMenuItem onSelect={() => onGenerate("comercios")}><Dice5 /> B2 · Comércio</ContextMenuItem>\n            <ContextMenuItem onSelect={() => onGenerate("eventos")}><Dice5 /> B3 · Evento</ContextMenuItem>\n            <ContextMenuSeparator />\n            <ContextMenuItem onSelect={onCreatePoint}><Plus /> Criar ponto manualmente</ContextMenuItem>\n          </ContextMenuSubContent>\n        </ContextMenuSub>\n\n        <ContextMenuSub>\n          <ContextMenuSubTrigger><Bug /> Infestação</ContextMenuSubTrigger>\n          <ContextMenuSubContent className="inventory-context-submenu">\n            {[0,1,2,3,4,5].map(value =>\n              <ContextMenuItem key={value} onSelect={() => run({ type: "infestation", value })}>\n                <Bug /> {value}/5{record.infestation === value ? " · atual" : ""}\n              </ContextMenuItem>)}\n            <ContextMenuSeparator />\n            <ContextMenuItem onSelect={() => run({ type: "infestation", value: null })}>\n              <Compass /> Deixar em aberto\n            </ContextMenuItem>\n          </ContextMenuSubContent>\n        </ContextMenuSub>\n\n        <ContextMenuItem onSelect={onOpenMasterTools}><Compass /> Ferramentas do mestre</ContextMenuItem>\n      </>}\n\n      {playerPreview && <ContextMenuItem disabled className="inventory-context-help">\n        <Footprints /> Ações de exploração ficam sob controle do mestre\n      </ContextMenuItem>}\n    </ContextMenuContent>\n  </ContextMenu>;\n}\n',
  "components/survivor-context-menu.tsx": '"use client";\n\nimport type { ReactElement } from "react";\nimport {\n  Activity,\n  ArrowLeftRight,\n  Backpack,\n  BookOpen,\n  Crosshair,\n  Dice5,\n  HeartPulse,\n  Shield,\n  Swords,\n  UserRound,\n  Wrench,\n} from "lucide-react";\nimport { toast } from "sonner";\nimport {\n  ContextMenu,\n  ContextMenuContent,\n  ContextMenuItem,\n  ContextMenuLabel,\n  ContextMenuSeparator,\n  ContextMenuSub,\n  ContextMenuSubContent,\n  ContextMenuSubTrigger,\n  ContextMenuTrigger,\n} from "@/components/ui/context-menu";\nimport type { RollRequest } from "@/components/roll-dialog";\nimport { itemActionOptions, performItemAction } from "@/lib/item-actions";\nimport { survivorStats, type GameState, type Survivor } from "@/lib/game";\n\ntype Edit = (fn: (draft: GameState) => void) => void;\n\nfunction qtyLabel(qty: number, total: number) {\n  return qty === total ? `Tudo · ${total}` : `${qty} unidade`;\n}\n\nexport function SurvivorContextMenu({\n  game,\n  edit,\n  survivor,\n  canControl,\n  masterMode,\n  onOpenTab,\n  onRoll,\n  children,\n}: {\n  game: GameState;\n  edit: Edit;\n  survivor: Survivor;\n  canControl: boolean;\n  masterMode: boolean;\n  onOpenTab: (tab: string) => void;\n  onRoll: (request: RollRequest) => void;\n  children: ReactElement;\n}) {\n  const stats = survivorStats(survivor);\n\n  function transfer(itemId: string, targetId: string, quantity: number) {\n    let result: ReturnType<typeof performItemAction> | null = null;\n    edit(draft => { result = performItemAction(draft, survivor.id, itemId, { type: "transfer", targetId, quantity }); });\n    if (!result?.ok) {\n      toast.error("A transferência não foi concluída.");\n      return;\n    }\n    toast.success(result.message);\n  }\n\n  return <ContextMenu>\n    <ContextMenuTrigger asChild>{children}</ContextMenuTrigger>\n    <ContextMenuContent className="inventory-context-menu survivor-context-menu">\n      <ContextMenuLabel className="inventory-context-header">\n        <b>{survivor.name}</b>\n        <span>PV {Math.max(0, stats.hp - survivor.hp)}/{stats.hp} · Hope {survivor.hope}/6 · Stress {survivor.stress}/6</span>\n      </ContextMenuLabel>\n      <ContextMenuSeparator />\n\n      <ContextMenuItem onSelect={() => onOpenTab("resumo")}><UserRound /> Abrir ficha</ContextMenuItem>\n      <ContextMenuSub>\n        <ContextMenuSubTrigger><BookOpen /> Ir para</ContextMenuSubTrigger>\n        <ContextMenuSubContent className="inventory-context-submenu">\n          <ContextMenuItem onSelect={() => onOpenTab("atributos")}><Dice5 /> Atributos e testes</ContextMenuItem>\n          <ContextMenuItem onSelect={() => onOpenTab("combate")}><Shield /> Combate e kit</ContextMenuItem>\n          <ContextMenuItem onSelect={() => onOpenTab("inventario")}><Backpack /> Inventário</ContextMenuItem>\n          <ContextMenuItem onSelect={() => onOpenTab("habilidades")}><Activity /> Habilidades</ContextMenuItem>\n          <ContextMenuItem onSelect={() => onOpenTab("condicoes")}><HeartPulse /> Condições</ContextMenuItem>\n          <ContextMenuItem onSelect={() => onOpenTab("historia")}><BookOpen /> História e notas</ContextMenuItem>\n        </ContextMenuSubContent>\n      </ContextMenuSub>\n\n      {canControl && <>\n        <ContextMenuSeparator />\n        <ContextMenuItem onSelect={() => onRoll({ survivorId: survivor.id, kind: "action" })}>\n          <Dice5 /> Rolar teste\n        </ContextMenuItem>\n        {(survivor.primary || survivor.secondary) && <ContextMenuSub>\n          <ContextMenuSubTrigger><Swords /> Rolar ataque</ContextMenuSubTrigger>\n          <ContextMenuSubContent className="inventory-context-submenu">\n            {survivor.primary && <ContextMenuItem onSelect={() => onRoll({ survivorId: survivor.id, kind: "attack", weapon: "primary" })}>\n              <Crosshair /> {survivor.primary}\n            </ContextMenuItem>}\n            {survivor.secondary && <ContextMenuItem onSelect={() => onRoll({ survivorId: survivor.id, kind: "attack", weapon: "secondary" })}>\n              <Crosshair /> {survivor.secondary}\n            </ContextMenuItem>}\n          </ContextMenuSubContent>\n        </ContextMenuSub>}\n      </>}\n\n      {masterMode && survivor.inventory.length > 0 && <ContextMenuSub>\n        <ContextMenuSubTrigger><ArrowLeftRight /> Transferir item</ContextMenuSubTrigger>\n        <ContextMenuSubContent className="inventory-context-submenu survivor-transfer-items">\n          {survivor.inventory.map(item => {\n            const options = itemActionOptions(game, survivor.id, item, false);\n            if (!options.targets.length) return null;\n            return <ContextMenuSub key={item.id}>\n              <ContextMenuSubTrigger><Backpack /> {item.name} · ×{item.qty}</ContextMenuSubTrigger>\n              <ContextMenuSubContent className="inventory-context-submenu">\n                {options.targets.map(target => item.qty === 1\n                  ? <ContextMenuItem key={target.value} onSelect={() => transfer(item.id, target.value, 1)}>\n                      <ArrowLeftRight /> {target.label}\n                    </ContextMenuItem>\n                  : <ContextMenuSub key={target.value}>\n                      <ContextMenuSubTrigger><ArrowLeftRight /> {target.label}</ContextMenuSubTrigger>\n                      <ContextMenuSubContent className="inventory-context-submenu">\n                        {[1, item.qty].map(qty =>\n                          <ContextMenuItem key={qty} onSelect={() => transfer(item.id, target.value, qty)}>\n                            <Backpack /> {qtyLabel(qty, item.qty)}\n                          </ContextMenuItem>)}\n                      </ContextMenuSubContent>\n                    </ContextMenuSub>)}\n              </ContextMenuSubContent>\n            </ContextMenuSub>;\n          })}\n        </ContextMenuSubContent>\n      </ContextMenuSub>}\n\n      {masterMode && <>\n        <ContextMenuSeparator />\n        <ContextMenuSub>\n          <ContextMenuSubTrigger><Wrench /> Mestre</ContextMenuSubTrigger>\n          <ContextMenuSubContent className="inventory-context-submenu">\n            <ContextMenuItem onSelect={() => onOpenTab("condicoes")}><HeartPulse /> Ajustar condição</ContextMenuItem>\n            <ContextMenuItem onSelect={() => onOpenTab("combate")}><Shield /> Registrar dano / recursos</ContextMenuItem>\n            <ContextMenuItem onSelect={() => onOpenTab("inventario")}><Backpack /> Gerenciar inventário</ContextMenuItem>\n          </ContextMenuSubContent>\n        </ContextMenuSub>\n      </>}\n\n      {!canControl && <ContextMenuItem disabled className="inventory-context-help">\n        <UserRound /> Visualização sem ações de personagem\n      </ContextMenuItem>}\n    </ContextMenuContent>\n  </ContextMenu>;\n}\n',
}
TESTS_APPEND = "\ntest('ações contextuais de hex respeitam avistamento, viagem e relógio', () => {\n  const g = campaign();\n  const start = content.hexes.find(hex => `${hex.q},${hex.r}` === g.partyHex);\n  assert.ok(start);\n  const neighbor = content.hexes.find(hex => require('../lib/game.ts').hexDistance(hex.q-start.q, hex.r-start.r) === 1);\n  assert.ok(neighbor);\n  const id = `${neighbor.q},${neighbor.r}`;\n  g.hexes[id].discovery = 'desconhecido';\n  g.hexes[id].sector = null;\n  const before = g.minutes;\n\n  let result = hexActions.performHexAction(g, id, { type:'observe' });\n  assert.equal(result.ok, true);\n  assert.equal(g.hexes[id].discovery, 'avistado');\n  const hours = g.hexes[id].routeHours;\n\n  result = hexActions.performHexAction(g, id, { type:'travel' });\n  assert.equal(result.ok, true);\n  assert.equal(g.partyHex, id);\n  assert.equal(g.hexes[id].discovery, 'explorado');\n  assert.equal(g.minutes, before + hours * 60);\n});\n\ntest('ações contextuais de hex controlam infestação e abrigo sem pular regras', () => {\n  const g = campaign();\n  const id = g.partyHex;\n  g.hexes[id].discovery = 'explorado';\n\n  let result = hexActions.performHexAction(g, id, { type:'infestation', value:4 });\n  assert.equal(result.ok, true);\n  assert.equal(g.hexes[id].infestation, 4);\n\n  result = hexActions.performHexAction(g, id, { type:'infestation', value:null });\n  assert.equal(result.ok, true);\n  assert.equal(g.hexes[id].infestation, null);\n\n  g.shelter.hex = null;\n  result = hexActions.performHexAction(g, id, { type:'establish' });\n  assert.equal(result.ok, true);\n  assert.equal(g.shelter.hex, id);\n\n  result = hexActions.performHexAction(g, id, { type:'establish' });\n  assert.equal(result.ok, false);\n});\n\ntest('menu de sobrevivente pode transferir item pelas regras centrais já usadas no inventário', () => {\n  const g = campaign(); const [ana, bia] = g.survivors;\n  ana.inventory = [item('Rádio portátil', 2)];\n  const radio = ana.inventory[0];\n  const options = itemActions.itemActionOptions(g, ana.id, radio, false);\n  assert.ok(options.targets.some(target => target.value === bia.id));\n\n  const result = itemActions.performItemAction(g, ana.id, radio.id, { type:'transfer', targetId:bia.id, quantity:1 });\n  assert.equal(result.ok, true);\n  assert.equal(ana.inventory.reduce((sum, entry) => sum + entry.qty, 0), 1);\n  assert.equal(bia.inventory.some(entry => entry.name === 'Rádio portátil'), true);\n});\n"
CSS_MARKER = '/* Context menus v3/v4: map and survivors */'
CSS_BLOCK = '\n/* Context menus v3/v4: map and survivors */\n.map-cell { cursor: context-menu; }\n.map-context-menu { min-width: 255px !important; }\n.survivor-context-target { cursor: context-menu; }\n.survivor-context-target:hover { box-shadow: inset 3px 0 #c79a5e; }\n.survivor-context-menu { min-width: 260px !important; }\n.survivor-transfer-items { max-height: min(420px,70vh); overflow-y:auto; }\n\n@media (hover:none) {\n  .map-cell,.survivor-context-target { cursor:pointer; }\n}\n'

required = ["lib/item-actions.ts", "components/item-context-menu.tsx", "lib/provision-items.ts"]
for path in required:
    if not (ROOT / path).exists():
        raise SystemExit(f"[ERRO] Falta {path}. Aplique primeiro as etapas anteriores (provisões físicas e menu contextual de inventário).")

def backup(path: str):
    src = ROOT / path
    dst = BACKUP / path
    dst.parent.mkdir(parents=True, exist_ok=True)
    if not dst.exists():
        shutil.copy2(src, dst)

def replace_once(path: str, old: str, new: str):
    file = ROOT / path
    if not file.exists():
        raise SystemExit(f"[ERRO] Arquivo não encontrado: {path}")
    text = file.read_text(encoding="utf-8")
    if new and new in text:
        print(f"[OK] {path}: alteração já aplicada.")
        return
    if not new and old not in text:
        print(f"[OK] {path}: trecho já removido.")
        return
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"[ERRO] {path}: trecho esperado encontrado {count} vez(es), deveria ser 1. Pare e envie este erro no chat.")
    backup(path)
    file.write_text(text.replace(old, new, 1), encoding="utf-8")
    print(f"[OK] {path}")

for path, content in NEW_FILES.items():
    file = ROOT / path
    if not file.exists():
        file.parent.mkdir(parents=True, exist_ok=True)
        file.write_text(content, encoding="utf-8")
        print(f"[OK] {path} criado.")
    elif content.strip() == file.read_text(encoding="utf-8").strip():
        print(f"[OK] {path} já presente.")
    else:
        raise SystemExit(f"[ERRO] {path} já existe com conteúdo diferente. Pare e envie este erro no chat.")

for path, old, new in REPLACEMENTS:
    replace_once(path, old, new)

